import { type } from "arktype";
export const solanaChargeMethodDetails = type({
    "network?": "string",
    "decimals?": "number",
    "tokenProgram?": "string",
    "feePayer?": "boolean",
    "feePayerKey?": "string",
    "recentBlockhash?": "string",
    "splits?": type({
        recipient: "string",
        amount: "string",
        "memo?": "string",
    }).array(),
});
export const mppChargeRequest = type({
    amount: "string.numeric",
    currency: "string",
    recipient: "string",
    "description?": "string",
    "externalId?": "string",
    "methodDetails?": solanaChargeMethodDetails,
});
export const chargeCredentialPayload = type({
    type: "'transaction'",
    transaction: "string",
}, "|", {
    type: "'signature'",
    signature: "string",
});
